import{_ as o,o as r,c as n,a6 as t}from"./chunks/framework.ZMCvXf1_.js";const p=JSON.parse('{"title":"Troubleshooting common surprises","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),a={name:"guide/troubleshooting.md"};function d(i,e,c,s,l,h){return r(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="troubleshooting-common-surprises" tabindex="-1">Troubleshooting common surprises <a class="header-anchor" href="#troubleshooting-common-surprises" aria-label="Permalink to “Troubleshooting common surprises”">​</a></h1><p>A short list of the issues users hit most often when first reaching for <code>noorm</code>. Each entry is a search target plus a one-paragraph fix and a link to the deeper doc.</p><h2 id="noorm-config-prod-run-build-fails-or-targets-the-wrong-directory" tabindex="-1"><code>noorm --config prod run build</code> fails or targets the wrong directory <a class="header-anchor" href="#noorm-config-prod-run-build-fails-or-targets-the-wrong-directory" aria-label="Permalink to “noorm --config prod run build fails or targets the wrong directory”">​</a></h2><p><code>--config</code> (long form) is per-subcommand only — it has no global meaning. Neither do <code>--dry-run</code>, <code>--json</code>, or <code>--yes</code>: the only flag with a root-level meaning is <code>-c</code>/<code>--cwd</code>. Placed before the subcommand, <code>--config</code> (and everything else) is rejected outright rather than silently ignored:</p><pre><code># rejected: --config has no global form
noorm --config prod run build

# works
noorm run build --config prod
noorm run build -c prod
</code></pre><p><code>-c</code> is the sharper trap: <code>noorm -c prod run build</code> is <em>not</em> the same command — before the subcommand, <code>-c</code> means <code>--cwd</code>, not <code>--config</code>. See <a href="./../cli/flags.html">CLI flag conventions</a> for the full rule.</p><h2 id="noorm-help-db-create-errors-with-unknown-command-help" tabindex="-1"><code>noorm help db create</code> errors with &quot;Unknown command help&quot; <a class="header-anchor" href="#noorm-help-db-create-errors-with-unknown-command-help" aria-label="Permalink to “noorm help db create errors with &quot;Unknown command help&quot;”">​</a></h2><p>There is no <code>noorm help &lt;subcommand&gt;</code> form — <code>noorm</code>&#39;s CLI framework (citty) doesn&#39;t ship one. Use <code>--help</code> (or <code>-h</code>) instead:</p><pre><code>noorm db create --help
noorm change ff --help
noorm sql query --help
</code></pre><p>See <a href="./../cli/help.html">Discovering command help</a>.</p><h2 id="noorm-db-create-name-foo-doesn-t-work" tabindex="-1"><code>noorm db create --name foo</code> doesn&#39;t work <a class="header-anchor" href="#noorm-db-create-name-foo-doesn-t-work" aria-label="Permalink to “noorm db create --name foo doesn&#39;t work”">​</a></h2><p><code>noorm db create</code> has no <code>--name</code> flag. The database name lives in the stored config; create the config first, then point <code>db create</code> at it. The intended workflow is:</p><pre><code>noorm config import dev-config.json
noorm db create -c dev
noorm config use dev
</code></pre><p>See <a href="./database/create.html">Creating a database</a> for the reasoning and the full CI bootstrap.</p><h2 id="my-mssql-proc-s-default-value-isn-t-applied" tabindex="-1">My MSSQL proc&#39;s <code>DEFAULT</code> value isn&#39;t applied <a class="header-anchor" href="#my-mssql-proc-s-default-value-isn-t-applied" aria-label="Permalink to “My MSSQL proc&#39;s DEFAULT value isn&#39;t applied”">​</a></h2><p>A Zod schema with <code>.optional()</code> parses missing keys to <code>undefined</code>. The SDK serializes <code>undefined</code> (and <code>null</code>) to SQL <code>NULL</code> when building a named-parameter <code>EXEC</code>. MSSQL applies a parameter&#39;s <code>DEFAULT</code> only when the parameter is <em>omitted</em> from the call, not when it&#39;s explicitly <code>NULL</code>. Two fixes:</p><ol><li>Use <code>.default(&lt;value&gt;)</code> in your Zod schema so the parsed input always carries a concrete value.</li><li>Or, build the params object without the key entirely (e.g. conditionally <code>delete obj.key</code> before calling <code>ctx.proc(...)</code>). The SDK only emits <code>@key = …</code> for keys present in the object.</li></ol><p>See <a href="./../reference/sdk.html#parameter-handling-and-null-semantics">SDK reference — Parameter handling and NULL semantics</a>.</p><h2 id="noorm-sql-select-errors-with-unknown-command" tabindex="-1"><code>noorm sql &quot;SELECT ...&quot;</code> errors with &quot;Unknown command&quot; <a class="header-anchor" href="#noorm-sql-select-errors-with-unknown-command" aria-label="Permalink to “noorm sql &quot;SELECT ...&quot; errors with &quot;Unknown command&quot;”">​</a></h2><p>The bare <code>noorm sql &quot;&lt;SQL&gt;&quot;</code> form is supported, but only when the first token of the query is one of the SQL verbs noorm rewrites on (<code>SELECT</code>, <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>WITH</code>, etc.). Citty resolves <code>sql</code>&#39;s subcommands first, so noorm rewrites <code>sql &lt;verb&gt; …</code> to <code>sql query &lt;verb&gt; …</code> before citty ever sees it. For anything that starts with a leading comment, a CTE-style preamble, or a non-recognized verb, use the explicit subcommand:</p><pre><code>noorm sql query &quot;&lt;your SQL&gt;&quot;
noorm sql query -f path/to/file.sql
</code></pre><p>See <a href="./../cli/sql.html"><code>noorm sql</code></a> for the full list of recognized keywords and when each form fires.</p><h2 id="noorm-change-ff-dry-run-wrote-files-i-didn-t-expect" tabindex="-1"><code>noorm change ff --dry-run</code> wrote files I didn&#39;t expect <a class="header-anchor" href="#noorm-change-ff-dry-run-wrote-files-i-didn-t-expect" aria-label="Permalink to “noorm change ff --dry-run wrote files I didn&#39;t expect”">​</a></h2><p><code>change ff</code> does accept <code>--dry-run</code>, and it does not touch the database. What it does do is <em>render</em> every pending change to <code>tmp/</code> so you can read the SQL that would have run, including any secrets the templates resolved, in plaintext. <code>tmp/</code> is not gitignored by a project noorm scaffolds, so clean it up.</p><pre><code>noorm change ff --dry-run
noorm run build --dry-run
</code></pre><p>To render a single template without the change machinery, use <code>noorm run preview &lt;path&gt;</code>. From the SDK the same preview is <code>changes.apply(name, { dryRun: true })</code> or <code>changes.ff({ dryRun: true })</code>.</p><h2 id="noorm-init-errors-in-ci-with-requires-an-interactive-terminal" tabindex="-1"><code>noorm init</code> errors in CI with &quot;requires an interactive terminal&quot; <a class="header-anchor" href="#noorm-init-errors-in-ci-with-requires-an-interactive-terminal" aria-label="Permalink to “noorm init errors in CI with &quot;requires an interactive terminal&quot;”">​</a></h2><p>The bootstrap path needs an existing identity at <code>~/.noorm/identity.{key,pub,json}</code>, then <code>--yes</code> (or <code>NOORM_YES=1</code>) skips every other prompt. Two commands:</p><pre><code>noorm identity init --name &quot;$CI_USER&quot; --email &quot;$CI_EMAIL&quot;
noorm init --yes
</code></pre><p>See <a href="./automation/non-interactive.html">Non-interactive operation</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./../cli/flags.html">CLI flag conventions</a></li><li><a href="./../cli/help.html">Discovering command help</a></li><li><a href="./database/create.html">Creating a database</a></li><li><a href="./automation/non-interactive.html">Non-interactive operation</a></li><li><a href="./../reference/sdk.html">SDK reference</a></li></ul>`,32)])])}const u=o(a,[["render",d]]);export{p as __pageData,u as default};
